import db from "@/config/db"
import { CourseChaptersTable, ExerciseTable } from "@/config/schema";
import { NextRequest, NextResponse } from "next/server";

const DATA = [
    { courseId: 1, exerciseId: "functional-components", exerciseName: "Functional Components", chapterId: 2, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to the Functional Components level 🎮 In React, components are like characters in a game, and functional components are the simplest and most powerful ones. A functional component is just a JavaScript function that returns UI. Think of it as a machine: input goes in, UI comes out. Earlier, class components were popular, but functional components are now the main heroes because they are easier to read and write. A functional component always starts with a capital letter so React can recognize it. Inside the function, you return JSX, which tells React what to show on the screen. This return works like the final animation frame of a game character. Functional components are reusable, lightweight, and fast. They also work perfectly with modern React features like hooks. When the browser loads your app, React calls these functions to render the UI. Every time state or props change, the function runs again, updating the screen. This makes your UI dynamic and interactive. Mastering functional components means you understand the core building block of React apps.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a functional component named <code>Player</code>. Inside it, return an <code><h2></code> that displays the text <code>Welcome Player</code>. Use this component inside the <code>App</code> component so it appears on the screen.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: A functional component is just a function. Example structure: <code>function Player(){ return(<h2>...</h2>); }</code>. Don’t forget to export it.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Welcome\s+Player", output: "Welcome Player", hintXp: 40 } },
    { courseId: 1, exerciseId: "component-reusability", exerciseName: "Component Reusability", chapterId: 2, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to the Reusability quest ♻️ In games, you don’t design a new sword for every enemy; you reuse the same weapon. React works the same way with components. Component reusability means creating one component and using it multiple times. This saves time, reduces bugs, and keeps code clean. A reusable component usually accepts data instead of hardcoding values. You can place the same component in different parts of your app. Each time React renders it, it behaves like a fresh instance. This makes your UI consistent and scalable. Big apps are built by combining small reusable components. If you update one reusable component, all places using it get updated automatically. This is a huge power-up for developers. Reusability also makes testing easier because each component has a single responsibility. Understanding this concept helps you think in components instead of pages.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a reusable component called <code>Card</code> that returns an <code><div></code> with text <code>Game Card</code>. Use this <code>Card</code> component three times inside the <code>App</code> component.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Import the same component and use it like a HTML tag multiple times: <code><Card /></code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Game\s+Card", output: "Game Card", hintXp: 35 } },
    { courseId: 1, exerciseId: "props-basics", exerciseName: "Props Basics", chapterId: 3, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to the Props tutorial level 🎁 Props are like power-ups you give to your components. The word props comes from properties. Props allow you to send data from one component to another. Usually, a parent component sends props to a child component. Props are read-only, meaning the child cannot change them. This keeps your data flow predictable. Think of props as messages passed to characters in a game. Each component can behave differently based on the props it receives. Props help make components reusable and dynamic. Without props, all components would look the same. React passes props as an object to the function. Inside the component, you access values using <code>props.propertyName</code>. Understanding props is essential to build interactive UIs. Once you master props, your components become flexible and powerful.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a component named <code>Title</code> that accepts a prop called <code>text</code>. Display this text inside an <code><h1></code>. Use the component inside <code>App</code> and pass <code>Hello Props</code> as the value.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Props are passed like attributes: <code><Title text='Hello Props' /></code> and accessed using <code>props.text</code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Hello\s+Props", output: "Hello Props", hintXp: 45 } },
    { courseId: 1, exerciseId: "passing-data-via-props", exerciseName: "Passing Data via Props", chapterId: 3, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>This level is all about data flow 🔄 Passing data via props is how components talk to each other in React. Data always flows from parent to child, like a game controller sending commands to characters. The parent decides what data to send, and the child simply uses it. This one-way flow makes apps easier to debug. You can pass strings, numbers, arrays, objects, or even functions as props. Each time the parent changes the data, the child re-renders automatically. This keeps UI in sync with data. Passing props helps break large UIs into smaller parts. It also makes your components independent and testable. Understanding this flow is critical for building real-world React apps. Once you get comfortable, you’ll design clean component trees.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a <code>User</code> component that receives <code>name</code> as a prop and displays <code>User: Mayank</code>. Pass the value from the <code>App</code> component.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Inside JSX, combine text and props like this: <code>User: {props.name}</code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "User:\sMayank", output: "User: Mayank", hintXp: 50 } },
    { courseId: 1, exerciseId: "props-destructuring", exerciseName: "Props Destructuring", chapterId: 3, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Final props level unlocked 🧩 Props destructuring is a cleaner way to use props. Instead of writing <code>props.name</code> again and again, you directly extract values. This makes code shorter and more readable. Destructuring happens inside the function parameters. It feels like selecting weapons directly instead of opening the full inventory each time. This is pure JavaScript, not React-specific, but very common in React apps. It improves clarity when components receive many props. Most professional React code uses destructuring. It does not change how props work internally. It only changes how you access them. Learning this helps you read and write modern React code confidently. It’s a small upgrade with a big impact on code quality.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a component <code>Score</code> that receives a prop <code>points</code> using destructuring and displays <code>Score: 100</code>. Pass the value from <code>App</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Use this syntax: <code>function Score({ points })</code> instead of using <code>props</code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Score:\s100", output: "Score: 100", hintXp: 35 } },

    { courseId: 1, exerciseId: "what-is-state", exerciseName: "What is State?", chapterId: 4, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to the State zone 🧠 In React, state is like the memory of a game character. It stores information that can change over time. Unlike normal variables, when state changes, React automatically re-renders the UI. This is the real magic of React. State is used for dynamic data like scores, counters, input values, or toggle states. Think of state as the current situation of your app at any moment. When something happens, like a button click, the state updates and the screen refreshes. State belongs to a component and is managed inside it. Each component can have its own state. This keeps data isolated and predictable. Without state, your app would be static like a paused game screen. Understanding state is essential to build interactive apps. Once you understand state, your UI starts feeling alive.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Think of a real-life example where data changes on user action. Create a simple React component and display a text <code>State makes UI dynamic</code> using JSX. No logic needed yet, just understand the concept.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: For now, focus on understanding what state is. You don’t need to write actual state logic in this task.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "State\s+makes\s+UI\s+dynamic", output: "State makes UI dynamic", hintXp: 30 } },
    { courseId: 1, exerciseId: "use-state-hook", exerciseName: "useState Hook", chapterId: 4, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Level up with useState ⚡ The <code>useState</code> hook is how functional components use state. Hooks are special functions provided by React. The <code>useState</code> hook gives you two things: the current state value and a function to update it. You initialize state with a default value. When you call the update function, React re-renders the component. This feels like pressing a button and watching the game world update instantly. Hooks must be called at the top level of the component. You cannot use them inside loops or conditions. The naming convention is important and makes code readable. With useState, you can build counters, forms, toggles, and more. It is one of the most used hooks in React. Mastering useState unlocks interactive UI development.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use the <code>useState</code> hook to create a counter starting at <code>0</code>. Display the value inside an <code><h1></code>. The output should initially show <code>0</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Import <code>useState</code> from React and use this pattern: <code>const [count,setCount]=useState(0)</code>.</body>", starterCode: { "App.jsx": "import React,{useState} from 'react';function App(){return(<div></div>);}export default App;" }, regex: "0", output: "0", hintXp: 45 } },
    { courseId: 1, exerciseId: "updating-state", exerciseName: "Updating State", chapterId: 4, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Now it’s action time 🔁 Updating state is how your app responds to user actions. You never change state directly. Instead, you use the updater function provided by useState. This ensures React knows when to re-render. Updating state is like leveling up a character, you don’t overwrite memory manually, the game engine handles it. State updates can be triggered by events like clicks or input changes. React batches updates to keep performance high. You can update state based on the previous value, which is very common. Understanding correct state updates prevents bugs and unexpected behavior. This concept is crucial as apps grow bigger. Clean state updates lead to predictable UI behavior.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a counter with a button. On button click, increase the count by <code>1</code>. Display the updated count on the screen.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Use <code>onClick</code> and update state like this: <code>setCount(count+1)</code>.</body>", starterCode: { "App.jsx": "import React,{useState} from 'react';function App(){const [count,setCount]=useState(0);return(<div></div>);}export default App;" }, regex: "\d+", output: "1", hintXp: 40 } },
    { courseId: 1, exerciseId: "event-handling", exerciseName: "Event Handling", chapterId: 4, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Event handling is how players interact with the game 🎮 In React, events are actions like clicks, typing, or hovering. React uses camelCase for event names like <code>onClick</code>. You pass a function to handle what happens when the event occurs. This keeps logic separate from UI. Event handling makes your app interactive. You can respond to user actions and update state accordingly. React events are similar to JavaScript events but work consistently across browsers. Events are a core part of building real-world apps. Without events, users couldn’t interact with your UI. Mastering events gives you control over user actions.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Add a button with text <code>Click Me</code>. When clicked, display a text <code>Button Clicked</code> on the screen.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Create a function and attach it to the button using <code>onClick</code>.</body>", starterCode: { "App.jsx": "import React,{useState} from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Button\s+Clicked", output: "Button Clicked", hintXp: 40 } },
    { courseId: 1, exerciseId: "controlled-inputs", exerciseName: "Controlled Inputs", chapterId: 4, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Boss level unlocked 🏆 Controlled inputs are inputs whose value is controlled by React state. This means the input value always comes from state. When the user types, an event updates the state, and the state updates the input. This gives React full control over form data. Controlled inputs are used in forms, search boxes, and login screens. They make validation and data handling easier. Without controlled inputs, managing user input becomes messy. This pattern ensures single source of truth. It might feel complex at first, but it’s extremely powerful. Most real-world React apps rely on controlled inputs. Once you master this, form handling becomes easy.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create an input field controlled by state. Display the typed text live below the input. Typing <code>React</code> should display <code>React</code> on the screen.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Use <code>value</code> and <code>onChange</code> on the input and update state using <code>e.target.value</code>.</body>", starterCode: { "App.jsx": "import React,{useState} from 'react';function App(){const [text,setText]=useState('');return(<div></div>);}export default App;" }, regex: "React", output: "React", hintXp: 70 } },


    { courseId: 1, exerciseId: "what-are-hooks", exerciseName: "What are Hooks?", chapterId: 5, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to the Hooks world 🪝 Hooks are special functions in React that let you use features like state and lifecycle inside functional components. Before hooks, only class components could manage state and side effects. Hooks removed this limitation and made functional components more powerful. Think of hooks as magic abilities you unlock for your character. Each hook gives a specific power like memory, effects, or context. Hooks always start with the word <code>use</code> so React can track them. They make code simpler, cleaner, and easier to reuse. Hooks also reduce boilerplate code compared to classes. With hooks, logic becomes easier to share between components. React internally manages how hooks work behind the scenes. Learning hooks is essential for modern React development. Once you understand hooks, you can build almost any feature using functional components.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Explain hooks in your own words by rendering a text <code>Hooks add powers to functional components</code> inside your React app.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: You only need JSX text for this task, no hook usage required yet.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Hooks\s+add\s+powers\s+to\s+functional\s+components", output: "Hooks add powers to functional components", hintXp: 30 } },
    { courseId: 1, exerciseId: "rules-of-hooks", exerciseName: "Rules of Hooks", chapterId: 5, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Every game has rules, and hooks are no different 📜 React hooks follow strict rules to work correctly. First rule: Hooks must be called at the top level of a component. This means no hooks inside loops, conditions, or nested functions. Second rule: Hooks must only be called inside React functional components or custom hooks. These rules help React keep hook state consistent across renders. If rules are broken, React cannot track hook order properly. Think of hooks like checkpoints in a game, they must appear in the same order every time. React relies on this order to map state correctly. Following rules avoids bugs and unexpected behavior. React even provides lint rules to warn you. Understanding these rules saves debugging time. Respecting hook rules makes your app stable and predictable.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Render a message <code>Hooks must be called at top level</code> inside a React component to show you understand the main rule.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Just render the text using JSX, no logic needed.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Hooks\s+must\s+be\s+called\s+at\s+top\s+level", output: "Hooks must be called at top level", hintXp: 35 } },
    { courseId: 1, exerciseId: "use-effect-basics", exerciseName: "useEffect Basics", chapterId: 5, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Now entering the effect zone ⚙️ The <code>useEffect</code> hook lets you run side effects in functional components. Side effects are actions like fetching data, updating the document title, or setting timers. useEffect runs after the component renders. You control when it runs using a dependency array. If the array is empty, the effect runs once on mount. If dependencies are provided, it runs when they change. Think of useEffect as background game logic running after each frame. It keeps your UI and external systems in sync. Without useEffect, managing side effects would be messy. This hook replaces lifecycle methods like componentDidMount. Understanding useEffect is key for real-world apps. It helps you connect React with the outside world.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use <code>useEffect</code> to log <code>Component Loaded</code> in the console when the component mounts.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Pass an empty dependency array <code>[]</code> as the second argument to <code>useEffect</code>.</body>", starterCode: { "App.jsx": "import React,{useEffect} from 'react';function App(){useEffect(()=>{},[]);return(<div>Check Console</div>);}export default App;" }, regex: "Check\s+Console", output: "Check Console", hintXp: 55 } },
    { courseId: 1, exerciseId: "effect-cleanup", exerciseName: "Effect Cleanup", chapterId: 5, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Cleanup time 🧹 Some effects need cleanup to avoid memory leaks. Examples include timers, subscriptions, or event listeners. useEffect allows cleanup by returning a function. This cleanup runs when the component unmounts or before the effect re-runs. Think of it as exiting a game level and clearing resources. Without cleanup, your app may slow down or behave incorrectly. Cleanup keeps your app efficient and bug-free. React automatically calls cleanup at the right time. This pattern is essential for performance. Many beginners forget cleanup, but professionals always include it when needed. Mastering cleanup means writing production-ready React code.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Write a <code>useEffect</code> that sets a timer and cleans it up using <code>clearInterval</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Return a function inside <code>useEffect</code> and clear the timer there.</body>", starterCode: { "App.jsx": "import React,{useEffect} from 'react';function App(){useEffect(()=>{const id=setInterval(()=>{},1000);return()=>clearInterval(id);},[]);return(<div>Cleanup Ready</div>);}export default App;" }, regex: "Cleanup\s+Ready", output: "Cleanup Ready", hintXp: 60 } },
    { courseId: 1, exerciseId: "hooks-recap-challenge", exerciseName: "Hooks Recap Challenge", chapterId: 5, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Final challenge unlocked 🏁 This level tests your hooks knowledge. Hooks allow functional components to manage state and effects. You learned what hooks are, their rules, how useState and useEffect work, and why cleanup matters. This challenge combines everything into one mental model. Think of hooks as the core engine of modern React. They simplify code and improve reusability. Understanding hooks means you can read and write professional React code. This recap helps solidify your learning. Completing this challenge means you are ready for advanced hooks. Stay consistent and keep practicing. Hooks mastery comes with repetition and real projects.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Render a message <code>Hooks Mastery Unlocked</code> to celebrate completing the hooks chapter.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Simple JSX text is enough for this challenge.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Hooks\s+Mastery\s+Unlocked", output: "Hooks Mastery Unlocked", hintXp: 70 } },

    { courseId: 1, exerciseId: "what-is-react", exerciseName: "What is React?", chapterId: 0, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to the React universe 🌍 React is a JavaScript library used to build user interfaces, especially for web applications. It was created by Facebook to solve problems related to fast and interactive UI updates. React focuses only on the view layer, meaning it handles what the user sees on the screen. Instead of manipulating the DOM directly, React uses a virtual DOM to update changes efficiently. Think of React as a smart game engine that updates only the parts of the screen that change. This makes applications faster and smoother. React is component-based, which means UI is broken into small reusable pieces. Each component manages its own logic and UI. React is widely used in industry because it scales well for large applications. Many popular apps like Instagram and Netflix use React. Learning React opens doors to modern frontend development.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Render a simple heading that says <code>React builds user interfaces</code> inside your app.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Just return an <code><h1></code> with the given text from your component.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "React\s+builds\s+user\s+interfaces", output: "React builds user interfaces", hintXp: 30 } },
    { courseId: 1, exerciseId: "why-react", exerciseName: "Why React?", chapterId: 0, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Why choose React? 🤔 React makes building complex UIs easier and more manageable. It uses a component-based architecture that promotes reusability. React updates the UI efficiently using the virtual DOM, improving performance. It has a huge community and strong ecosystem support. React code is predictable because of one-way data flow. It works well with modern tools and frameworks. React allows developers to focus on logic rather than manual DOM updates. It also supports server-side rendering and mobile app development through React Native. Companies trust React for scalability and maintainability. Learning React gives you industry-relevant skills. This is why React is one of the most popular frontend libraries today.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Display a paragraph with text <code>React makes UI development easier</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Use a <code><p></code> tag to show the message.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "React\s+makes\s+UI\s+development\s+easier", output: "React makes UI development easier", hintXp: 30 } },
    { courseId: 1, exerciseId: "react-vs-vanilla-js", exerciseName: "React vs Vanilla JS", chapterId: 0, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>React vs Vanilla JavaScript ⚔️ Vanilla JS means writing plain JavaScript to manipulate the DOM directly. This works fine for small projects but becomes hard to manage as apps grow. React abstracts DOM manipulation using components and state. In Vanilla JS, you manually update elements, while React automatically updates UI when data changes. React code is more structured and reusable. Vanilla JS gives full control but requires more effort. React improves developer productivity and maintainability. React handles UI updates efficiently, reducing bugs. Both use JavaScript, but React provides a better architecture for large apps. Choosing React helps you build scalable applications faster.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Render text <code>React manages UI updates automatically</code> on the screen.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Any JSX element displaying the text is acceptable.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "React\s+manages\s+UI\s+updates\s+automatically", output: "React manages UI updates automatically", hintXp: 35 } },
    { courseId: 1, exerciseId: "spa-concept", exerciseName: "SPA Concept", chapterId: 0, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Single Page Application explained 📄 A SPA loads a single HTML page and updates content dynamically without reloading the page. React is commonly used to build SPAs. Navigation feels faster because only data is exchanged, not full pages. SPAs provide a smooth user experience similar to mobile apps. React handles routing and component rendering efficiently. Traditional websites reload pages, causing delays. SPAs improve performance and responsiveness. State management plays a key role in SPAs. React works well with APIs in SPA architecture. Understanding SPA helps you understand modern web apps.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Show a message <code>SPA loads once and updates dynamically</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Render the text directly inside JSX.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "SPA\s+loads\s+once\s+and\s+updates\s+dynamically", output: "SPA loads once and updates dynamically", hintXp: 35 } },
    { courseId: 1, exerciseId: "react-ecosystem", exerciseName: "React Ecosystem", chapterId: 0, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>The React ecosystem 🌐 React is more than just a library. It comes with a powerful ecosystem of tools and libraries. Common tools include React Router for routing and Redux for state management. Build tools like Vite and Webpack help bundle apps. UI libraries like Material UI speed up development. Testing libraries help ensure app quality. The ecosystem allows you to pick tools based on project needs. This flexibility is a big advantage. The ecosystem is actively maintained by the community. Knowing the ecosystem helps you build production-ready apps.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Display a line <code>React ecosystem powers modern apps</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: A simple JSX text output is enough.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "React\s+ecosystem\s+powers\s+modern\s+apps", output: "React ecosystem powers modern apps", hintXp: 35 } },

    { courseId: 1, exerciseId: "rendering-lists", exerciseName: "Rendering Lists", chapterId: 6, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to the Lists arena 📋 Rendering lists in React means showing multiple items from an array on the screen. Instead of writing UI again and again, React lets you generate UI from data. Think of a game inventory where items are displayed based on what you collect. Each item in an array becomes a visual element. React re-renders the list automatically when data changes. This makes UIs dynamic and data-driven. Lists are everywhere: menus, cards, notifications, comments. Rendering lists keeps code short and scalable. The list rendering process usually combines arrays with JSX. Understanding list rendering helps you move from static pages to real apps. Once you master this, your UI can grow with your data.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create an array of fruits and render them as a list on the screen. Make sure at least one item shows <code>Apple</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Store items in an array and loop over it to return JSX elements.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const items=[];return(<div></div>);}export default App;" }, regex: "Apple", output: "Apple", hintXp: 35 } },
    { courseId: 1, exerciseId: "map-function-jsx", exerciseName: "Map Function in JSX", chapterId: 6, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Power move unlocked: map 🗺️ The <code>map</code> function is the most common way to render lists in React. It loops over an array and returns a new array of JSX elements. Think of it as cloning a game character for each item with slight differences. Map keeps your code clean and expressive. Inside JSX, you can directly use <code>array.map()</code>. Each iteration returns one UI element. React then renders all of them together. This pattern is efficient and readable. Using map avoids manual loops and DOM handling. It’s a core React skill used everywhere. Mastering map means mastering list rendering.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use <code>map</code> to render numbers <code>1, 2, 3</code> on the screen.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Example pattern: <code>numbers.map(num => <p>{num}</p>)</code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const numbers=[1,2,3];return(<div></div>);}export default App;" }, regex: "1|2|3", output: "1 2 3", hintXp: 40 } },
    { courseId: 1, exerciseId: "why-keys-matter", exerciseName: "Why Keys Matter", chapterId: 6, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Why keys exist 🔑 Keys help React identify which items in a list have changed. When lists update, React compares old and new items. Keys act like unique IDs for game characters. Without keys, React may re-render inefficiently or incorrectly. Keys improve performance and prevent UI bugs. They tell React which element stays, moves, or gets removed. Keys should be stable and predictable. Index keys work sometimes but are not recommended for dynamic lists. Understanding keys helps you avoid warnings and bugs. React relies heavily on keys during reconciliation. Using keys correctly is a best practice.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Render a list of items using <code>map</code> and add a <code>key</code> prop to each element.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Add <code>key={value}</code> to the root element returned inside map.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const items=['A','B','C'];return(<div></div>);}export default App;" }, regex: "A|B|C", output: "A B C", hintXp: 35 } },
    { courseId: 1, exerciseId: "unique-keys", exerciseName: "Unique Keys", chapterId: 6, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Choosing the right key 🎯 Keys must be unique among siblings. Using unique IDs ensures React tracks items correctly. Think of keys as player IDs, not player positions. Using indexes as keys can cause issues when items are reordered or removed. Unique keys keep UI consistent during updates. IDs from databases are perfect keys. If no ID exists, generate one carefully. Correct keys reduce unnecessary re-renders. This improves performance and stability. Many bugs in lists come from bad keys. Learning this makes your lists production-ready.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Render a list of users with unique IDs and use those IDs as keys. Ensure one user named <code>Mayank</code> is displayed.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Store users as objects like <code>{id:1,name:'Mayank'}</code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const users=[];return(<div></div>);}export default App;" }, regex: "Mayank", output: "Mayank", hintXp: 35 } },
    { courseId: 1, exerciseId: "dynamic-lists-practice", exerciseName: "Dynamic Lists Practice", chapterId: 6, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Final list challenge 🏁 Dynamic lists change based on data or user actions. Combining state with lists lets you add or remove items. This is common in todo apps, carts, and dashboards. React updates the list automatically when state changes. Map and keys work together to keep UI in sync. Think of adding items to an inventory during gameplay. Dynamic lists are a core real-world use case. Mastering them prepares you for complex apps. This practice brings together arrays, map, keys, and state. Completing this means you truly understand lists in React.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a dynamic list using state. Display a list of items and ensure at least one item shows <code>Task 1</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Use <code>useState</code> to store an array and render it with <code>map</code>.</body>", starterCode: { "App.jsx": "import React,{useState} from 'react';function App(){const [tasks,setTasks]=useState([]);return(<div></div>);}export default App;" }, regex: "Task\s*1", output: "Task 1", hintXp: 65 } },

    { courseId: 1, exerciseId: "if-else-rendering", exerciseName: "If-Else Rendering", chapterId: 7, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to conditional rendering 🧩 In React, if-else rendering lets you show different UI based on conditions. Think of it like game logic where different screens appear based on player status. React does not allow traditional if-else directly inside JSX, but you can use it before the return statement. You decide which JSX to return based on a condition. This is useful for login checks, loading screens, and feature toggles. Conditional rendering helps keep UI dynamic and responsive. It allows your app to react to state changes intelligently. Instead of showing everything at once, you show only what matters. This improves user experience and clarity. If-else logic keeps components readable when conditions are complex. Understanding this pattern is a foundation for real-world React apps. Once mastered, your UI will feel smart and adaptive.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use if-else logic to render <code>Welcome User</code> when a variable <code>isLoggedIn</code> is true, otherwise render <code>Please Login</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Write the if-else condition before the return statement and return different JSX blocks.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const isLoggedIn=true;return(<div></div>);}export default App;" }, regex: "Welcome\s+User|Please\s+Login", output: "Welcome User", hintXp: 40 } },
    { courseId: 1, exerciseId: "ternary-operator", exerciseName: "Ternary Operator", chapterId: 7, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Speed up rendering with ternary ⚡ The ternary operator is a compact way to write conditions in JSX. It works like a quick decision-making tool in a game. The syntax includes a condition, a true result, and a false result. Ternary operators are perfect for simple conditions. They are written directly inside JSX, unlike if-else blocks. This keeps code short and readable. Ternary rendering is often used for toggles, status messages, and UI switches. Overusing ternary for complex logic can reduce readability. Use it wisely for clean code. React developers use ternary operators very frequently. Mastering this makes your JSX expressive and concise.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use a ternary operator to display <code>Online</code> if <code>isOnline</code> is true, otherwise display <code>Offline</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Syntax example: <code>{condition ? 'Yes' : 'No'}</code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const isOnline=true;return(<div></div>);}export default App;" }, regex: "Online|Offline", output: "Online", hintXp: 40 } },
    { courseId: 1, exerciseId: "logical-and-rendering", exerciseName: "Logical AND (&&)", chapterId: 7, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Conditional shortcut unlocked 🔓 Logical AND rendering uses the <code>&&</code> operator. It renders content only when the condition is true. If the condition is false, nothing is shown. This is useful when you don’t need an else case. Think of it as showing a bonus item only when a player unlocks it. This pattern keeps JSX clean and readable. It works best for optional UI elements. React ignores false values and renders nothing. Many developers prefer this for simple checks. Logical AND avoids unnecessary else logic. It is commonly used for alerts, badges, and conditional sections. Mastering this makes your JSX minimal and elegant.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use logical AND to display <code>New Message</code> only when <code>hasMessage</code> is true.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Use this pattern: <code>{hasMessage && 'New Message'}</code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const hasMessage=true;return(<div></div>);}export default App;" }, regex: "New\s+Message", output: "New Message", hintXp: 40 } },
    { courseId: 1, exerciseId: "loading-states", exerciseName: "Loading States", chapterId: 7, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Handling loading like a pro ⏳ Loading states tell users that something is happening. Without loading indicators, apps feel broken. In React, loading state is usually handled with a boolean state variable. While data is loading, you show a spinner or message. Once data arrives, you show the real content. This is like a loading screen before a game level starts. Loading states improve user experience and trust. They are essential when fetching data from APIs. Conditional rendering controls what appears during loading. Every real-world app uses loading states. Understanding this helps you build professional interfaces.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use a loading state to display <code>Loading...</code> when <code>isLoading</code> is true, otherwise show <code>Data Loaded</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Combine state with ternary rendering to switch UI.</body>", starterCode: { "App.jsx": "import React,{useState} from 'react';function App(){const [isLoading,setIsLoading]=useState(true);return(<div></div>);}export default App;" }, regex: "Loading\.\.\.|Data\s+Loaded", output: "Loading...", hintXp: 45 } },
    { courseId: 1, exerciseId: "auth-based-ui", exerciseName: "Auth Based UI", chapterId: 7, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Boss level: Auth based UI 🔐 Auth based UI changes the interface based on user authentication. Logged-in users see dashboards, while guests see login screens. This is core to most applications. React handles this using state and conditional rendering. Think of locked areas in a game that open only for logged-in players. Auth based UI improves security and personalization. It keeps features hidden from unauthorized users. This pattern combines if-else, ternary, and logical AND. Almost every production app uses this concept. Mastering this prepares you for real-world projects. Once you understand auth-based UI, your apps feel complete and realistic.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Show <code>Dashboard</code> when <code>isAuthenticated</code> is true, otherwise show <code>Login Page</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Use conditional rendering with a boolean auth variable.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){const isAuthenticated=true;return(<div></div>);}export default App;" }, regex: "Dashboard|Login\s+Page", output: "Dashboard", hintXp: 65 } },

    { courseId: 1, exerciseId: "create-react-app-vite", exerciseName: "Create React App / Vite", chapterId: 1, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to your React journey 🚀 Creating a React app is like starting a new game world. Vite is a modern build tool that helps you create React apps extremely fast. Earlier, Create React App was common, but Vite is lighter and much faster. Vite gives instant server start and super fast hot reload. This means when you change code, the browser updates instantly. To create a project, you run <code>npm create vite@latest</code> and choose React. After setup, <code>npm install</code> downloads dependencies like game assets. Running <code>npm run dev</code> starts the local server. Your app runs in the browser on localhost. Vite handles bundling and development configuration for you. You don’t need to worry about complex setup. This allows you to focus on learning React itself. Think of Vite as a speed booster that removes loading screens. Faster feedback means faster learning and better experience.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a React app using Vite and render a heading that says <code>Hello React</code> on the screen.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Edit the <code>App.jsx</code> file and return an <code><h1></code> element.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Hello\s+React", output: "Hello React", hintXp: 40 } },
    { courseId: 1, exerciseId: "project-folder-tour", exerciseName: "Project Folder Tour", chapterId: 1, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Let’s explore the project map 🗺️ A React project created with Vite has a clear folder structure. The <code>src</code> folder is where most of your work happens. Inside it, <code>main.jsx</code> is the entry point of the app. It connects React to the browser DOM. The <code>App.jsx</code> file is your main component. This is where UI starts. The <code>public</code> folder stores static files like images. Configuration files live at the root. Understanding the folder structure is like learning the game controls. It helps you know where to add or change code. Without this knowledge, projects feel confusing. With it, you can move confidently. A clear structure also helps teamwork and scalability.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Open <code>App.jsx</code> and display a text <code>This is App Component</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Everything you return from <code>App</code> appears on the screen.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "This\s+is\s+App\s+Component", output: "This is App Component", hintXp: 35 } },
    { courseId: 1, exerciseId: "jsx-basics", exerciseName: "JSX Basics", chapterId: 1, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Welcome to JSX 🎨 JSX stands for JavaScript XML. It allows you to write HTML-like code inside JavaScript. JSX makes UI code readable and expressive. Behind the scenes, JSX is converted into JavaScript by React. JSX lets you mix logic and markup in one place. This feels like designing a game scene with code. You can use expressions inside JSX using curly braces. JSX is not HTML, but it looks similar. React components return JSX to describe UI. JSX improves developer experience and clarity. Almost all React apps use JSX. Once you get comfortable, writing UI feels natural. JSX is one of React’s biggest strengths.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Use JSX to render <code>JSX is powerful</code> inside an <code><h2></code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: JSX looks like HTML but lives inside JavaScript.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "JSX\s+is\s+powerful", output: "JSX is powerful", hintXp: 40 } },
    { courseId: 1, exerciseId: "jsx-rules", exerciseName: "JSX Rules", chapterId: 1, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Every system has rules 📜 JSX also follows strict rules. JSX must return a single parent element. You cannot return two sibling elements without wrapping them. JSX tags must be properly closed. JavaScript expressions go inside curly braces. Class names use <code>className</code> instead of class. These rules help React parse JSX correctly. Breaking rules causes errors. Think of JSX rules like game physics; ignore them and things break. Once you learn the rules, JSX becomes predictable. These rules keep UI code consistent. Most JSX errors come from rule violations. Learning them early saves debugging time.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Render two text lines inside a single parent element showing <code>JSX Rules Followed</code>.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Wrap multiple elements inside a <code><div></code>.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "JSX\s+Rules\s+Followed", output: "JSX Rules Followed", hintXp: 35 } },
    { courseId: 1, exerciseId: "first-react-component", exerciseName: "First React Component", chapterId: 1, exercisesContent: { content: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>Congratulations on your first component 🎉 A React component is a reusable piece of UI. Components are like characters in a game that you can reuse anywhere. A functional component is just a JavaScript function that returns JSX. Component names must start with a capital letter. Components help split UI into small, manageable pieces. This makes code easier to read and maintain. React apps are built by combining components. Each component focuses on one job. Reusability is the biggest advantage of components. Once created, you can use a component many times. This is the foundation of React development. Mastering components means mastering React.</body>", task: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>🎯 Mission: Create a component called <code>Hello</code> and display <code>Hello Component</code> using it.</body>", hint: "<body style='font-family:system-ui;line-height:1.6;color:#e5e7eb;'>💡 Hint: Define a function and use it like <code><Hello /></code> inside App.</body>", starterCode: { "App.jsx": "import React from 'react';function App(){return(<div></div>);}export default App;" }, regex: "Hello\s+Component", output: "Hello Component", hintXp: 45 } }
]

export async function GET(req:NextRequest) {
    DATA.forEach(async (item) => {
        await db.insert(ExerciseTable).values({
            courseId: item?.courseId,
            chapterId: item?.chapterId,
            exerciseId: item?.exerciseId,
            exerciseName: item?.exerciseName,
            exercisesContent: item?.exercisesContent
        })
    })

    return NextResponse.json('Success')
}



